    return f"open {path}: no such file or directory"

# ----------------- Go formatting helpers -----------------

def _shortest_digits(v):
    # returns (digits_str, exp10) where value = digits[0].digits[1:] * 10**exp10, sign handled outside
    if v == 0:
        return ("0", 0)
    r = repr(abs(v))
