# ---------------- Tokenizer ----------------

SEPARATORS = set(',;()=')

def tokenize(query):
    tokens = []
    i = 0
    n = len(query)
    while i < n:
        c = query[i]
        if c.isspace():
            tokens.append(c)
            i += 1
            continue
        if c in SEPARATORS:
            tokens.append(c)
            i += 1
            continue
        # word token, may include quoted sections
        start = i
        quote = None
        while i < n:
            c = query[i]
            if quote is not None:
                if c == quote:
                    # check doubled
                    if i + 1 < n and query[i+1] == quote:
                        i += 2
                        continue
                    else:
                        quote = None
                        i += 1
                        continue
                else:
                    i += 1
                    continue
            else:
                if c in ('"', "'", '`'):
                    quote = c
                    i += 1
                    continue
                if c.isspace() or c in SEPARATORS:
                    break
                i += 1
        tokens.append(query[start:i])
    return tokens

