    o = ord(c)
    if o == '\n':
        return "'\\n'"
    if o == '\r':
        return "'\\r'"
    if o == '\t':
        return "'\\t'"
    if 0x20 <= o < 0x7f:
        return f"'{c}'"
    if o < 0x20:
        return "'\\u%04x'" % o
    return f"'{c}'"

