                        new.append(None)
            else:
                new.append(v)
        results=new
    return results

def jq_eval(node, value):
    # generator
    typ=node[0]
    if typ=='literal':
        yield node[1]; return
    if typ=='path':
        suffixes=node[1]
        yield from jq_apply_path(value, suffixes)
        return
    if typ=='apply_path':
        for v in jq_eval(node[1], value):
            yield from jq_apply_path(v, node[2])
        return
    if typ=='pipe':
        for v in jq_eval(node[1], value):
            yield from jq_eval(node[2], v)
        return
    if typ=='comma':
        yield from jq_eval(node[1], value)
        yield from jq_eval(node[2], value)
        return
    if typ=='arrayctor':
        arr=[]
        for v in jq_eval(node[1], value):
            arr.append(v)
        yield arr; return
    if typ=='objctor':
        obj={}
        # note: values may produce multiple outputs; jq takes cross-product, simplify first
        for k, vnode in node[1]:
            vals=list(jq_eval(vnode, value))
            obj[k]=vals[0] if vals else None
        yield obj; return
    if typ=='binop':
        op=node[1]
        if op=='and':
            left=list(jq_eval(node[2], value))
            # evaluate truthiness
            for lv in left:
                if jq_truthy(lv):
                    yield from jq_eval(node[3], value)
                else:
                    yield False
            return
        if op=='or':
            left=list(jq_eval(node[2], value))
            for lv in left:
                if jq_truthy(lv):
                    yield True
                else:
                    yield from jq_eval(node[3], value)
            return
        lefts=list(jq_eval(node[2], value))
        rights=list(jq_eval(node[3], value))
        for lv in lefts:
            for rv in rights:
                yield jq_binop(op, lv, rv)
        return
    if typ=='func':
        name=node[1]; args=node[2]
        yield from jq_func(name, args, value)
        return
    yield value

def jq_truthy(v):
    return not (v is False or v is None)

def jq_num(v):
    if isinstance(v, JsonNumber):
        try:
            if '.' in str(v) or 'e' in str(v) or 'E' in str(v): return float(v)
            return int(v)
        except: return float(v)
    if isinstance(v, bool):
        raise JQError(f'expected a number but got: {jq_preview(v)}')
    if isinstance(v, (int,float)): return v
    raise JQError(f'expected a number but got: {jq_preview(v)}')

def jq_binop(op, lv, rv):
    if op=='==': return jq_equal(lv,rv)
    if op=='!=': return not jq_equal(lv,rv)
    if op in ('>','<','>=','<='):
        # compare: simplify for numbers/strings
        a=jq_num(lv) if isinstance(lv,(int,float,JsonNumber)) and not isinstance(lv,bool) else lv
        b=jq_num(rv) if isinstance(rv,(int,float,JsonNumber)) and not isinstance(rv,bool) else rv
        try:
            if op=='>': return a>b
            if op=='<': return a<b
            if op=='>=': return a>=b
            if op=='<=': return a<=b
        except Exception:
            return False
    if op=='+':
        if lv is None: return rv
        if rv is None: return lv
        if isinstance(lv,(int,float,JsonNumber)) and isinstance(rv,(int,float,JsonNumber)): return jq_num(lv)+jq_num(rv)
        if isinstance(lv,str) and isinstance(rv,str): return lv+rv
        if isinstance(lv,list) and isinstance(rv,list): return lv+rv
        if isinstance(lv,dict) and isinstance(rv,dict):
            o=dict(lv); o.update(rv); return o
        raise JQError(f'expected a number but got: {jq_preview(lv)}')
    if op=='-':
        return jq_num(lv)-jq_num(rv)
    if op=='*':
        return jq_num(lv)*jq_num(rv)
    if op=='/':
        return jq_num(lv)/jq_num(rv)
    if op=='%':
        return jq_num(lv)%jq_num(rv)
    return None

def jq_equal(a,b):
    # numeric compare across JsonNumber
    if isinstance(a, JsonNumber): a=jq_num(a)
    if isinstance(b, JsonNumber): b=jq_num(b)
    return a==b

def jq_func(name, args, value):
    if name=='map':
        if not args: yield value; return
        if not isinstance(value, list):
            raise JQError(f'expected an array but got: {jq_preview(value)}')
        out=[]
        for el in value:
            out.extend(jq_eval(args[0], el))
        yield out; return
    if name=='map_values':
        if isinstance(value, list):
            out=[]
            for el in value: out.extend(jq_eval(args[0], el))
            yield out; return
        if isinstance(value, dict):
            out={}
            for k,el in value.items():
                vals=list(jq_eval(args[0], el))
                if vals: out[k]=vals[0]
            yield out; return
        yield value; return
    if name=='select':
        if not args: yield value; return
        for v in jq_eval(args[0], value):
            if jq_truthy(v):
                yield value
        return
    if name=='length':
        if value is None: yield 0; return
        if isinstance(value,(str,list,dict)): yield len(value); return
        if isinstance(value,(int,float,JsonNumber)): yield abs(jq_num(value)); return
        raise JQError(f'expected a string or array but got: {jq_preview(value)}')
    if name=='keys':
        if isinstance(value, dict): yield sorted(value.keys()); return
        if isinstance(value, list): yield list(range(len(value))); return
        raise JQError(f'expected an object but got: {jq_preview(value)}')
    if name=='values':
        if value is not None: yield value
        return
    if name=='nulls':
        if value is None: yield value
        return
    if name=='type':
        yield jq_type_name(value); return
    if name=='tostring':
        if isinstance(value,str): yield value
        else: yield json_compact(value)
        return
    if name=='tonumber':
        if isinstance(value,str):
            try:
                if '.' in value: yield float(value)
                else: yield int(value)
            except:
                raise JQError(f'expected a number but got: string ({json_compact(value)})')
        else: yield jq_num(value)
        return
    if name=='to_entries':
        if isinstance(value, dict):
            yield [{'key':k,'value':v} for k,v in value.items()]; return
        raise JQError(f'expected an object but got: {jq_preview(value)}')
    if name=='from_entries':
        if isinstance(value, list):
            obj={}
            for e in value:
                if isinstance(e,dict) and 'key' in e: obj[e['key']]=e.get('value')
            yield obj; return
        yield value; return
    if name=='has':
        if args:
            ks=list(jq_eval(args[0], value))
            for k in ks:
                if isinstance(value,dict): yield k in value
                elif isinstance(value,list): yield isinstance(k,int) and 0<=k<len(value)
                else: yield False
        return
    if name=='first':
        if args:
            # first(f)
            for v in jq_eval(args[0], value):
                yield v; break
            return
        if isinstance(value,list) and value: yield value[0]
        elif isinstance(value,list): yield None
        return
    if name=='last':
        if args:
            vals=list(jq_eval(args[0], value)); yield vals[-1] if vals else None; return
        if isinstance(value,list) and value: yield value[-1]
        return
    if name=='reverse':
        if isinstance(value,list): yield list(reversed(value)); return
        if isinstance(value,str): yield value[::-1]; return
        yield value; return
    if name=='sort':
        if isinstance(value,list):
            try: yield sorted(value, key=lambda x: json_compact(x))
            except: yield value
            return
        yield value; return
    if name=='unique':
        if isinstance(value,list):
            seen=[]; out=[]
            for x in value:
                if x not in seen: seen.append(x); out.append(x)
            yield out; return
        yield value; return
    if name=='flatten':
        def flat(lst):
            out=[]
            for x in lst:
                if isinstance(x,list): out.extend(flat(x))
                else: out.append(x)
            return out
        if isinstance(value,list): yield flat(value); return
        yield value; return
    if name=='min':
        if isinstance(value,list) and value:
            yield min(value, key=lambda x: jq_num(x) if isinstance(x,(int,float,JsonNumber)) else str(x)); return
        yield None; return
    if name=='max':
        if isinstance(value,list) and value:
            yield max(value, key=lambda x: jq_num(x) if isinstance(x,(int,float,JsonNumber)) else str(x)); return
        yield None; return
    if name=='join':
        if args and isinstance(value,list):
            seps=list(jq_eval(args[0], value))
            sep=str(seps[0]) if seps else ''
            yield sep.join('' if x is None else (x if isinstance(x,str) else parsed_scalar_to_cell(x)) for x in value); return
        yield value; return
    if name=='split':
        if args and isinstance(value,str):
            seps=list(jq_eval(args[0], value))
            sep=str(seps[0]) if seps else ''
            yield value.split(sep); return
        yield value; return
    if name=='empty':
        return
    if name=='error':
        raise JQError('error')
    if name=='not':
        yield not jq_truthy(value); return
    if name=='keys_unsorted':
        if isinstance(value,dict): yield list(value.keys()); return
        if isinstance(value,list): yield list(range(len(value))); return
        return
    # unknown function: gojq would be parse error "function not defined"
    raise JQError(f'function not defined: {name}', True)

def apply_jq(expr, value):
    # returns list of outputs; may raise JQError with formatted message augmentation done by caller
    parser = JQParser(expr)
    node = parser.parse()
    return list(jq_eval(node, value))

