# ---------------- jq subset ----------------

class JQError(Exception):
    def __init__(self, msg, is_parse=False):
        super().__init__(msg)
        self.msg = msg
        self.is_parse = is_parse

def jq_format_value(v):
    # truncated representation like gojq errors
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, (JsonNumber,int,float)):
        return str(v)
    if isinstance(v, str):
        return f'"{v}"'
    if isinstance(v, list):
        s = json_compact(v)
        if len(s) > 27:
            s = s[:27] + ' ...'
        return f'array ({s})'
    if isinstance(v, dict):
        s = json_compact(v)
        if len(s) > 27:
            s = s[:27] + ' ...'
        return f'object ({s})'
    return str(v)

def jq_type_name(v):
    if v is None: return 'null'
    if isinstance(v, bool): return 'boolean'
    if isinstance(v, (int,float,JsonNumber)): return 'number'
    if isinstance(v, str): return 'string'
    if isinstance(v, list): return 'array'
    if isinstance(v, dict): return 'object'
    return 'null'

def jq_preview(v):
    # e.g. array ([{"id":"1","name":"Orange ...])
    if isinstance(v, list):
        s = json_compact(v)
        if len(s) > 27:
            s = s[:27] + ' ...'
        return f'array ({s})'
    if isinstance(v, dict):
        s = json_compact(v)
        if len(s) > 27:
            s = s[:27] + ' ...'
        return f'object ({s})'
    return jq_type_name(v) + f' ({json_compact(v) if not isinstance(v,str) else chr(34)+v+chr(34)})' if False else jq_format_value(v)

class JQParser:
    def __init__(self, text):
        self.s = text
        self.n = len(text)
        self.i = 0
    def error(self, msg):
        raise JQError(msg, True)
    def skip(self):
        while self.i < self.n and self.s[self.i] in ' \t\r\n':
            self.i += 1
    def peek(self):
        self.skip()
        return self.s[self.i] if self.i < self.n else ''
    def expect(self, ch):
        self.skip()
        if self.i < self.n and self.s[self.i] == ch:
            self.i += 1
            return True
        return False
    def parse(self):
        if self.s.strip() == '':
            self.error('unexpected end of jq expression')
        node = self.parse_pipe()
        self.skip()
        if self.i < self.n:
            c = self.s[self.i]
            # produce gojq-like token error
            tok = self.read_token_for_error()
            self.error(f'unexpected token "{tok}"')
        return node
    def read_token_for_error(self):
        self.skip()
        if self.i >= self.n: return ''
        c = self.s[self.i]
        if c.isalnum() or c == '_':
            j=self.i
            while j<self.n and (self.s[j].isalnum() or self.s[j]=='_'): j+=1
            tok=self.s[self.i:j]; self.i=j; return tok
        else:
            self.i+=1; return c
    def parse_pipe(self):
        left = self.parse_comma()
        while True:
            self.skip()
            if self.i < self.n and self.s[self.i] == '|':
                self.i += 1
                right = self.parse_comma()
                left = ('pipe', left, right)
            else:
                break
        return left
    def parse_comma(self):
        left = self.parse_term_chain()
        while True:
            self.skip()
            if self.i < self.n and self.s[self.i] == ',':
                self.i += 1
                right = self.parse_term_chain()
                left = ('comma', left, right)
            else:
                break
        return left
    def parse_term_chain(self):
        # parse a primary term, with possible postfix path suffixes handled inside
        node = self.parse_primary()
        # operators for comparison / arithmetic (used inside select etc)
        while True:
            self.skip()
            op = None
            for cand in ('==','!=','>=','<=','>','<','+','-','*','/','%','and','or'):
                if cand in ('and','or'):
                    if self.s.startswith(cand, self.i) and (self.i+len(cand)>=self.n or not (self.s[self.i+len(cand)].isalnum() or self.s[self.i+len(cand)]=='_')):
                        op=cand; break
                elif self.s.startswith(cand, self.i):
                    op=cand; break
            if op is None:
                break
            self.i += len(op)
            right = self.parse_primary()
            node = ('binop', op, node, right)
        return node
    def parse_primary(self):
        self.skip()
        if self.i >= self.n:
            self.error('unexpected end of jq expression')
        c = self.s[self.i]
        if c == '.':
            return self.parse_dot()
        if c == '(':
            self.i += 1
            node = self.parse_pipe()
            self.skip()
            if not self.expect(')'):
                self.error('unexpected end of jq expression')
            # suffixes after paren
            node = self.apply_suffixes(node)
            return node
        if c == '"':
            s = self.parse_jq_string()
            return ('literal', s)
        if c == '[':
            # array construction [expr, ...] or empty
            self.i += 1
            self.skip()
            if self.expect(']'):
                return ('literal', [])
            inner = self.parse_pipe()
            self.skip(); self.expect(']')
            return ('arrayctor', inner)
        if c == '{':
            # object construction simple: {key: expr, "key": expr, .key}
            self.i += 1
            pairs=[]
            self.skip()
            if self.expect('}'):
                return ('literal', {})
            while True:
                self.skip()
                if self.i < self.n and self.s[self.i]=='"':
                    k=self.parse_jq_string()
                elif self.i < self.n and self.s[self.i]=='.':
                    # shorthand .foo
                    self.i+=1
                    k=self.parse_ident()
                    pairs.append((k, ('path', [('field',k)])))
                    self.skip()
                    if self.expect(','): continue
                    else: break
                else:
                    k=self.parse_ident()
                self.skip()
                if self.expect(':'):
                    v=self.parse_term_chain()
                    pairs.append((k,v))
                else:
                    pairs.append((k, ('path',[('field',k)])))
                self.skip()
                if self.expect(','): continue
                else: break
            self.skip(); self.expect('}')
            return ('objctor', pairs)
        if c.isdigit() or (c=='-' and self.i+1<self.n and self.s[self.i+1].isdigit()):
            # number literal
            m=re.match(r'-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?', self.s[self.i:])
            txt=m.group(0); self.i+=len(txt)
            # keep as JsonNumber if integer? use Python int/float conversion simple
            if '.' in txt or 'e' in txt or 'E' in txt:
                return ('literal', float(txt))
            else:
                return ('literal', int(txt))
        if c.isalpha() or c=='_' or c=='$':
            ident = self.parse_ident_full()
            if ident == 'null': return ('literal', None)
            if ident == 'true': return ('literal', True)
            if ident == 'false': return ('literal', False)
            # function call?
            self.skip()
            if self.i < self.n and self.s[self.i]=='(':
                self.i+=1
                args=[]
                self.skip()
                if not self.expect(')'):
                    while True:
                        args.append(self.parse_pipe())
                        self.skip()
                        if self.expect(';') or self.expect(','):
                            # gojq uses ; for args, but in map(...) only one; accept both ; as separator
                            continue
                        break
                    self.skip(); self.expect(')')
                return ('func', ident, args)
            else:
                return ('func', ident, [])
        # invalid token
        tok = self.read_token_for_error()
        self.error(f'unexpected token "{tok}"')
    def parse_ident(self):
        self.skip()
        m=re.match(r'[A-Za-z_][A-Za-z0-9_]*', self.s[self.i:])
        if not m:
            tok=self.read_token_for_error(); self.error(f'unexpected token "{tok}"')
        self.i+=len(m.group(0)); return m.group(0)
    def parse_ident_full(self):
        m=re.match(r'\$?[A-Za-z_][A-Za-z0-9_]*', self.s[self.i:])
        txt=m.group(0); self.i+=len(txt); return txt
    def parse_jq_string(self):
        # use JSON parser for string
        p=JSONParser(self.s[self.i:])
        try:
            v=p.parse_string()
        except Exception:
            self.error('invalid string')
        self.i += p.i
        return v
    def parse_dot(self):
        # starting at '.'
        self.i += 1  # consume .
        suffixes=[]
        # .foo, ."foo", .[..], .[] etc; also bare . is identity
        while True:
            if self.i < self.n and (self.s[self.i].isalpha() or self.s[self.i]=='_'):
                name=self.parse_ident()
                suffixes.append(('field', name))
                # continue for .another handled below if '.' follows? Actually .a.b: loop will see '.'
                # Need loop handling: if next char is '.' and following is ident/[ - it's a continuation
                # We'll let code proceed to check dot
            elif self.i < self.n and self.s[self.i]=='"':
                name=self.parse_jq_string()
                suffixes.append(('field', name))
            elif self.i < self.n and self.s[self.i]=='[':
                suffixes.extend(self.parse_bracket_suffix())
            else:
                break
            # optional ?
            if self.i < self.n and self.s[self.i]=='?':
                # mark last as optional
                if suffixes:
                    typ,val = suffixes[-1]
                    suffixes[-1]=(typ+'?',val) if False else (typ, val, True)
                self.i+=1
            # if next is '.' followed by ident/[ / " then continue
            if self.i < self.n and self.s[self.i]=='.':
                # peek next
                if self.i+1 < self.n and (self.s[self.i+1].isalpha() or self.s[self.i+1] in '_"['):
                    self.i+=1
                    continue
            break
        return ('path', suffixes)
    def parse_bracket_suffix(self):
        # at '['
        self.i+=1
        self.skip()
        res=[]
        if self.i < self.n and self.s[self.i]==']':
            self.i+=1
            res.append(('iterate',None))
            return res
        if self.i < self.n and self.s[self.i]=='"':
            name=self.parse_jq_string()
            self.skip(); self.expect(']')
            res.append(('field',name)); return res
        # number or slice or expression?
        # try number / slice
        save=self.i
        m=re.match(r'-?\d+', self.s[self.i:])
        if m:
            # lookahead for ] or :
            j=self.i+len(m.group(0))
            k=j
            while k<self.n and self.s[k] in ' \t': k+=1
            if k<self.n and self.s[k]==']':
                self.i=k+1
                res.append(('index',int(m.group(0)))); return res
            if k<self.n and self.s[k]==':':
                # slice
                start=int(m.group(0))
                self.i=k+1
                self.skip()
                m2=re.match(r'-?\d+', self.s[self.i:])
                end=None
                if m2: end=int(m2.group(0)); self.i+=len(m2.group(0))
                self.skip(); self.expect(']')
                res.append(('slice',(start,end))); return res
        # slice with empty start :end
        if self.i < self.n and self.s[self.i]==':':
            self.i+=1; self.skip()
            m2=re.match(r'-?\d+', self.s[self.i:])
            end=None
            if m2: end=int(m2.group(0)); self.i+=len(m2.group(0))
            self.skip(); self.expect(']')
            res.append(('slice',(None,end))); return res
        # general expression [expr]
        self.i=save
        inner=self.parse_pipe()
        self.skip(); self.expect(']')
        res.append(('index_expr',inner)); return res
    def apply_suffixes(self, node):
        # after parenthesised expr, suffixes like .foo or [0] or []
        while True:
            self.skip()
            if self.i < self.n and self.s[self.i]=='.':
                # dot suffix
                dotnode=self.parse_dot()
                # dotnode is path applied to node
                node=('apply_path', node, dotnode[1])
                continue
            if self.i < self.n and self.s[self.i]=='[':
                sufs=self.parse_bracket_suffix()
                node=('apply_path', node, sufs)
                continue
            break
        return node

def jq_apply_path(value, suffixes):
    # generator of outputs
    results=[value]
    for suf in suffixes:
        optional=False
        if len(suf)==3:
            typ,val,optional = suf
        else:
            typ,val = suf
        new=[]
        for v in results:
            if typ=='field':
                if v is None:
                    new.append(None)
                elif isinstance(v, dict):
                    new.append(v.get(val, None))
                else:
                    if optional:
                        continue
                    # gojq error: expected an object but got: ...
                    if isinstance(v, list):
                        raise JQError(f'expected an object but got: {jq_preview(v)}')
                    elif isinstance(v, str):
                        raise JQError(f'expected an object but got: string ({json_compact(v)})')
                    elif isinstance(v, bool):
                        raise JQError(f'expected an object but got: boolean ({json_compact(v)})')
                    elif isinstance(v, (int,float,JsonNumber)):
                        raise JQError(f'expected an object but got: number ({v})')
                    else:
                        raise JQError(f'expected an object but got: {jq_preview(v)}')
            elif typ=='index':
                idx=val
                if v is None:
                    new.append(None)
                elif isinstance(v, list):
                    if -len(v) <= idx < len(v):
                        new.append(v[idx])
                    else:
                        new.append(None)
                else:
                    if optional: continue
                    if isinstance(v, dict):
                        raise JQError(f'expected an array but got: {jq_preview(v)}')
                    elif isinstance(v, str):
                        raise JQError(f'expected an array but got: string ({json_compact(v)})')
                    else:
                        raise JQError(f'expected an array but got: {jq_preview(v)}')
            elif typ=='slice':
                start,end=val
                if v is None:
                    new.append(None)
                elif isinstance(v, (list,str)):
                    new.append(v[slice(start,end)])
                else:
