        return jq_num(lv)-jq_num(rv)
    if op=='*':
        return jq_num(lv)*jq_num(rv)
    if op=='/':
        return jq_num(lv)/jq_num(rv)
    if op=='%':
        return jq_num(lv)%jq_num(rv)
    return None

