    if t in ('false','False','FALSE'):
        return False
    low = t.lower()
    # inf / nan
    if low in ('.inf','+.inf'):
        return math.inf
    if low == '-.inf':
        return -math.inf
    if low == '.nan':
        return math.nan
    # ints
    sign = 1
    body = t
    if body and body[0] in '+-':
        if body[0]=='-': sign=-1
        body=body[1:]
    if re.fullmatch(r'0x[0-9a-fA-F_]+', body):
