    if re.fullmatch(r'0o[0-7_]+', body):
        return sign*int(body[2:].replace('_',''),8)
    if re.fullmatch(r'0b[01_]+', body):
        return sign*int(body[2:].replace('_',''),2)
    if re.fullmatch(r'0[0-7_]+', body):
        return sign*int(body.replace('_',''),8)
    if re.fullmatch(r'(0|[1-9][0-9_]*)', body):
        return sign*int(body.replace('_',''),10)
