        c=sep[i]
        if c!='\\':
            out.append(c); i+=1; continue
        i+=1
        if i>=len(sep): raise ValueError()
        e=sep[i]; i+=1
        mapping={'a':'\a','b':'\b','f':'\f','n':'\n','r':'\r','t':'\t','v':'\v','\\':'\\','"':'"',"'":"'"}
        if e in mapping: out.append(mapping[e])
        elif e=='x':
            if i+2>len(sep): raise ValueError()
            out.append(chr(int(sep[i:i+2],16))); i+=2
        elif e=='u':
            if i+4>len(sep): raise ValueError()
            out.append(chr(int(sep[i:i+4],16))); i+=4
        elif e=='U':
            if i+8>len(sep): raise ValueError()
            out.append(chr(int(sep[i:i+8],16))); i+=8
        elif e in '01234567':
            # need total 3 octal digits including e
            if i+2>len(sep): raise ValueError()
            digits=e+sep[i:i+2]
            if not all(d in '01234567' for d in digits): raise ValueError()
            out.append(chr(int(digits,8))); i+=2
        else:
            raise ValueError()
    return ''.join(out)

