    # inner is content between ??? We'll parse a full row like "| a | b |"
    # Returns list of cell strings decoded
    cells=[]
    # row must be handled by scanning
    s=inner
    # Expect s starts with | and ends with |
    # We'll parse using state: separators are single | not doubled and not \|
    parts=[]
    cur=[]
    i=0
    while i<len(s):
        c=s[i]
        if c=='\\' and i+1<len(s) and s[i+1]=='|':
            cur.append('\\|'); i+=2; continue
        if c=='|':
            # count run
            j=i
            while j<len(s) and s[j]=='|': j+=1
            run=j-i
            if run==1:
                parts.append(''.join(cur)); cur=[]; i=j; continue
            else:
                # run of >=2: decode to run-1 literals? For reading, || -> one literal, remaining... simplify:
                # Convert run to (run-1) literal pipes and treat no separator (except maybe ???)
