# ---------------- output sink ----------------

class Sink:
    def __init__(self, raw_stream, compression=None, is_stdout=True):
        self.raw=raw_stream
        self.comp=compression
        self.buf=bytearray()
        self.closed=False
    def write(self, data):
        if isinstance(data,str):
            data=data.encode('utf-8','surrogateescape')
        self.buf.extend(data)
    def write_str(self, s):
        self.write(s)
    def flush_final(self):
        if self.closed: return
        self.closed=True
        data=bytes(self.buf)
        out=data
        if self.comp=='gz':
            out=gzip_compress_go(data)
        elif self.comp=='bz2':
            out=bz2.compress(data, compresslevel=6)
        elif self.comp=='xz':
            out=lzma.compress(data, format=lzma.FORMAT_XZ, check=lzma.CHECK_CRC64, preset=6)
        elif self.comp=='zstd':
            out=zstd_compress(data)
        elif self.comp=='lz4':
            out=lz4_frame_compress(data)
        try:
            self.raw.write(out)
            self.raw.flush()
        except BrokenPipeError:
            pass

def gzip_compress_go(data):
    out=bytearray()
    out.extend(b'\x1f\x8b\x08\x00\x00\x00\x00\x00\x00\xff')
    comp=zlib.compressobj(6, zlib.DEFLATED, -15)
    out.extend(comp.compress(data)); out.extend(comp.flush())
    out.extend(struct.pack('<I', zlib.crc32(data)&0xffffffff))
    out.extend(struct.pack('<I', len(data)&0xffffffff))
    return bytes(out)

def guess_output_format_and_compression(opts):
    # returns (format_kind, compression)
    # explicit format priority handled separately
    comp=None
    fmt='CSV'
    name=opts.out
    # Determine compression extension and strip
    # Recognized compression suffixes in guessing: .gz .bz2 .xz .zst .lz4 (not .zstd)
    comp_map={'.gz':'gz','.bz2':'bz2','.xz':'xz','.zst':'zstd','.lz4':'lz4'}
    base=name
    ext=_file_ext(base).lower()
    if ext in comp_map:
        comp=comp_map[ext]
        base=_trim_ext(base)
        ext=_file_ext(base).lower()
    fmt_map={'.csv':'CSV','.json':'JSON','.jsonl':'JSONL','.ltsv':'LTSV','.md':'MD','.tbln':'TBLN','.yaml':'YAML','.yml':'YAML','.at':'AT','.vf':'VF','.raw':'RAW'}
    if ext in fmt_map:
        fmt=fmt_map[ext]
    return fmt, comp

def explicit_output_format(opts):
    # priority: LTSV > JSON > RAW > MD > AT > VF > TBLN > JSONL > YAML > CSV
    if opts.oltsv: return 'LTSV'
    if opts.ojson: return 'JSON'
    if opts.oraw: return 'RAW'
    if opts.omd: return 'MD'
    if opts.oat: return 'AT'
    if opts.ovf: return 'VF'
    if opts.otbln: return 'TBLN'
    if opts.ojsonl: return 'JSONL'
    if opts.oyaml: return 'YAML'
    if opts.ocsv: return 'CSV'
    return None

# ---------------- writers ----------------

def _null_replaced(v, opts):
    if v is None and opts.onull_set:
        return opts.onull
    return v

def _row_strings(columns, row, opts):
    out=[]
    for v in row:
        vv=_null_replaced(v, opts)
        if vv is None:
            out.append('')
        else:
            out.append(value_to_string(vv))
    return out

class Writer:
    def __init__(self, sink, opts):
        self.sink=sink; self.opts=opts
    def write_result(self, columns, rows):
        raise NotImplementedError

class CSVWriter(Writer):
    def __init__(self, sink, opts, raw=False):
        super().__init__(sink,opts); self.raw=raw
        self.delim=get_output_delimiter(opts.od)
        self.quote=opts.oq if opts.oq!='' else '\x00'
    def _needs_quote(self, field):
        if self.opts.oaq:
            return True
        if field=='':
            return False
        if field=='\\.':
            return True
        if self.delim in field: return True
        # quote char: first char of quote string? Go custom uses quote string; check contains the quote char (first rune)
        q=self.quote[0] if len(self.quote)>0 else '\x00'
        if q in field: return True
        if '\r' in field or '\n' in field: return True
        if field and field[0]==' ': return True
        return False
    def _format_field(self, field, is_null):
        if self.raw:
            return field
        if is_null and not self.opts.oaq:
            # null with onull already converted; actual null prints empty unquoted even with oaq? Original: oaq null remaining empty unquoted
            # Our caller passes is_null based on original value None and not onull_set
            return ''
        if self.opts.oaq or self._needs_quote(field):
            q=self.quote
            # Go custom writer doubles quote string? For default " it doubles the quote character.
            # Escape occurrences of the quote string / char
            if len(q)==1:
                escaped=field.replace(q, q+q)
            else:
                escaped=field.replace(q, q+q)
            return q+escaped+q
        return field
    def write_result(self, columns, rows):
        line_ending='\r\n' if (self.opts.ocrlf and not self.raw) else '\n'
        # CSV CRLF only applies when output is to file? Original observed stdout no crlf, file yes.
        # We implement: sink attribute 'crlf_effective' set by main when out file is used.
        if not getattr(self.sink,'crlf_effective',False):
            line_ending='\n'
        if self.opts.oh:
            fields=[]
            for c in columns:
                fields.append(self._format_field(c, False))
            self.sink.write(self.delim.join(fields)+line_ending)
        for row in rows:
            fields=[]
            for v in row:
                is_null=(v is None and not self.opts.onull_set)
                vv=_null_replaced(v,self.opts)
                s='' if vv is None else value_to_string(vv)
                if self.raw:
                    fields.append(s)
                else:
                    # oaq: quote non-null fields (including empty string); null unquoted
                    if is_null:
                        fields.append('')
                    else:
                        fields.append(self._format_field(s, False))
            self.sink.write(self.delim.join(fields)+line_ending)

class JSONWriter(Writer):
    def __init__(self, sink, opts, lines=False):
        super().__init__(sink,opts); self.lines=lines
    def _convert(self, v):
        if v is None:
            return self.opts.onull if self.opts.onull_set else None
        if isinstance(v, bytes):
            s=value_to_string(v)
            return self._convert_str(s)
        if isinstance(v, str):
            return self._convert_str(v)
        return v
    def _convert_str(self, s):
        if s.startswith('[') or s.startswith('{'):
            try:
                p=JSONParser(s)
                val=p.parse_value_stream()
                p.skip_ws()
                if p.i!=p.n:
                    return s
                return self._convert_numbers(val)
            except Exception:
                return s
        return s
    def _convert_numbers(self, v):
        if isinstance(v, JsonNumber):
            txt=str(v)
            if '.' in txt or 'e' in txt or 'E' in txt:
                return float(txt)
            else:
                try:
                    iv=int(txt)
                    if iv>9223372036854775807 or iv<-9223372036854775808:
                        return float(txt)
                    return iv
                except:
                    return float(txt)
        if isinstance(v, list):
            return [self._convert_numbers(x) for x in v]
        if isinstance(v, dict):
            return {k:self._convert_numbers(val) for k,val in v.items()}
        return v
    def _row_obj(self, columns, row):
        obj={}
        for c,v in zip(columns,row):
            obj[c]=self._convert(v)
        return obj
    def write_result(self, columns, rows):
        if self.lines:
            for row in rows:
                obj=self._row_obj(columns,row)
                try:
                    s=go_json_marshal(obj)
                except ValueError as e:
                    # extract inf value label
                    raise ExportErr('json: error calling MarshalJSON for type *orderedmap.OrderedMap: json: unsupported value: +Inf' if self._has_inf(obj) else str(e))
                self.sink.write(s+'\n')
        else:
            objs=[]
            for row in rows:
                objs.append(self._row_obj(columns,row))
            try:
                s=go_json_marshal(objs, indent='  ')
            except ValueError as e:
                raise ExportErr('json: error calling MarshalJSON for type *orderedmap.OrderedMap: json: unsupported value: +Inf' if self._has_inf(objs) else str(e))
            self.sink.write(s+'\n')
    def _has_inf(self, v):
        if isinstance(v,float) and math.isinf(v): return True
        if isinstance(v,dict): return any(self._has_inf(x) for x in v.values())
        if isinstance(v,list): return any(self._has_inf(x) for x in v)
        return False

class LTSVWriter(Writer):
    def write_result(self, columns, rows):
        for row in rows:
            strs=_row_strings(columns,row,self.opts)
            parts=[f"{col}:{val}" for col,val in zip(columns,strs)]
            self.sink.write('\t'.join(parts)+'\n')

class TBLNWriter(Writer):
    def _escape(self, s):
        s=s.replace('\n','\\n')
        # pipe escaping: each maximal run of '|' gets one additional '|'
        s=re.sub(r'\|+', lambda m: m.group(0)+'|', s)
        return s
    def write_result(self, columns, rows):
        self.sink.write('; name: | '+' | '.join(self._escape(c) for c in columns)+' |\n')
        self.sink.write('; type: | '+' | '.join(['text']*len(columns))+' |\n')
        for row in rows:
            strs=_row_strings(columns,row,self.opts)
            self.sink.write('| '+' | '.join(self._escape(s) for s in strs)+' |\n')

class VFWriter(Writer):
    def write_result(self, columns, rows):
        # column width
        maxlen=max((len(c) for c in columns), default=0)
        if maxlen==0: maxlen=1
        for idx,row in enumerate(rows, start=1):
            self.sink.write(f"---[ {idx}]------------------------\n")
            strs=_row_strings(columns,row,self.opts)
            for col,val in zip(columns,strs):
                self.sink.write(f"  {col:>{maxlen}} | {val}\n")

# YAML conversion / emitter

def _sort_nested(v):
    if isinstance(v, dict):
        return {k:_sort_nested(v[k]) for k in sorted(v.keys(), key=lambda x: str(x))}
    if isinstance(v, list):
        return [_sort_nested(x) for x in v]
    return v

def yaml_guess_value(s):
    if s=='':
        return None
    # Use YAML document parser for the string
    try:
        docs=parse_yaml_documents(s)
    except Exception:
        return s
    if len(docs)==0:
        return None
    if len(docs)>1:
        return s
    v=docs[0]
    # if the flow parse may have ignored trailing content, fallback for strings starting [/{ but not ending matching
    st=s.strip()
    if st.startswith('[') and not st.endswith(']'):
        return s
    if st.startswith('{') and not st.endswith('}'):
        return s
    # For plain strings, parser will have resolved etc.
    # Tab/CR mangling observed for plain text values: if original was plain (not quoted/flow) and contains tab/cr
    if isinstance(v,str):
        # If input string was quoted in s, parser returns exact; our heuristic: if s doesn't start with quote/bracket, apply tab removal / CR to space?
        if not st.startswith(('"',"'",'[','{')):
            # v already may contain tabs if it was plain; apply
            v=v.replace('\t','').replace('\r',' ')
    return _sort_nested(v) if isinstance(v,(dict,list)) else v

def yaml_string_repr(s):
    if s=='':
        return '""'
    # double quote if ambiguous or special
    low=s.lower()
    needs=False
    # ambiguous types
    if s.strip()!=s: needs=True
    if low in ('yes','no','on','off','y','n','true','false','null','~',''): needs=True
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}([ T].*)?', s): needs=True
    if re.fullmatch(r'\d{4}-\d{2}-\d{2} \d{2}:\d{2}(:\d{2})?', s): needs=True
    # would resolve as non-string
    try:
        rv=yaml_resolve_plain(s)
        if not isinstance(rv,str):
            needs=True
    except Exception:
        pass
    if s and s[0] in '!&*?|>%@`\'",#[]{}':
        needs=True
    if s.startswith('- ') or s=='-' or s.startswith(': ') or s.startswith('? ') or s.startswith('#'):
        needs=True
    if ': ' in s or s.endswith(':') or ' #' in s:
        needs=True
    if any(ord(ch)<0x20 for ch in s):
        needs=True
    if '"' in s or '\\' in s:
        # strings with quote/backslash may be plain in some cases (a "b" was plain), but backslash example in yaml output "a\\tb" was via guess fallback;
        # Only force if begins problematic... Keep plain if only internal double quote
        if '\\' in s:
            needs=True
    if needs:
        out='"'
        for ch in s:
            if ch=='"': out+='\\"'
            elif ch=='\\': out+='\\\\'
            elif ch=='\n': out+='\\n'
            elif ch=='\r': out+='\\r'
            elif ch=='\t': out+='\\t'
            elif ord(ch)<0x20: out+='\\x%02x'%ord(ch)
            else: out+=ch
        out+='"'
        return out
    return s

def yaml_key_repr(k):
    return yaml_string_repr(str(k))

def _is_nonempty_dict(v): return isinstance(v,dict) and len(v)>0
def _is_nonempty_list(v): return isinstance(v,list) and len(v)>0

def yaml_inline(v):
    if v is None: return 'null'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,int): return str(v)
    if isinstance(v,float): return go_yaml_float(v)
    if isinstance(v,str): return yaml_string_repr(v)
    if isinstance(v,bytes): return yaml_string_repr(v.decode('utf-8','replace'))
    if isinstance(v,dict):
        if len(v)==0: return '{}'
        return '{}'  # handled by block; fallback
    if isinstance(v,list):
        if len(v)==0: return '[]'
        return '[]'
    return yaml_string_repr(str(v))

def yaml_block_lines(v, indent):
    lines=[]
    if isinstance(v,dict):
        if len(v)==0:
            return [' '*indent+'{}']
        for k,val in v.items():
            ks=yaml_key_repr(k)
            prefix=' '*indent+ks+':'
            if _is_nonempty_dict(val):
                lines.append(prefix)
                lines.extend(yaml_block_lines(val, indent+2))
            elif _is_nonempty_list(val):
                lines.append(prefix)
                lines.extend(yaml_block_lines(val, indent))
            else:
                # inline value could be empty dict/list
                if isinstance(val,dict): lines.append(prefix+' {}')
                elif isinstance(val,list): lines.append(prefix+' []')
                else: lines.append(prefix+' '+yaml_inline(val))
        return lines
    if isinstance(v,list):
        if len(v)==0:
            return [' '*indent+'[]']
        for item in v:
            if _is_nonempty_dict(item) or _is_nonempty_list(item):
                sub=yaml_block_lines(item, indent+2)
                first=' '*indent+'- '+sub[0][indent+2:]
                lines.append(first); lines.extend(sub[1:])
            else:
                if isinstance(item,dict): lines.append(' '*indent+'- {}')
                elif isinstance(item,list): lines.append(' '*indent+'- []')
                else: lines.append(' '*indent+'- '+yaml_inline(item))
        return lines
    return [' '*indent+yaml_inline(v)]

class YAMLWriter(Writer):
    def _convert(self, v):
        if v is None:
            if self.opts.onull_set:
                return self.opts.onull  # string, emitter will quote if needed
            return None
        if isinstance(v, bytes):
            # raw bytes: decode with replace but preserve NUL
            s=v.decode('utf-8','replace')
            # yaml guess on blob? ab -> plain; use string as is (no guess for binary-ish)
            if '\ufffd' in s or '\x00' in s:
                return s
            return yaml_guess_value(s)
        if isinstance(v, str):
            return yaml_guess_value(v)
        return v
    def write_result(self, columns, rows):
        if len(rows)==0:
            self.sink.write('[]\n'); return
        out_lines=[]
        for row in rows:
            obj={}
            for c,v in zip(columns,row):
                obj[c]=self._convert(v)
            lines=yaml_block_lines(obj,2)
            if lines:
                # first line: replace leading 2 spaces with '- '
                lines[0]='- '+lines[0][2:]
                out_lines.extend(lines)
        self.sink.write('\n'.join(out_lines)+'\n')

# Table writer (AT / MD)

def display_width(s):
    w=0
    for ch in s:
        o=ord(ch)
        if o==0: continue
        if unicodedata_east(ch): w+=2
        else: w+=1
    return w

def unicodedata_east(ch):
    import unicodedata
    eaw=unicodedata.east_asian_width(ch)
    return eaw in ('W','F')

def wrap_line(line, limit=30):
    # tablewriter WrapString-like: wrap at whitespace to limit display width, long words kept
    if display_width(line)<=limit:
        return [line]
    # split by spaces preserving? tablewriter uses words
    words=line.split(' ')
    # If only one word, return as is
    if len(words)<=1:
        return [line]
    lines=[]
    cur=''
    for word in words:
        if cur=='':
            cur=word
        elif display_width(cur)+1+display_width(word)<=limit:
            cur+=' '+word
        else:
            lines.append(cur); cur=word
    if cur!='' or not lines:
        lines.append(cur)
    return lines

def _is_numeric_cell(s):
    t=s.strip()
    if t=='':
        return False
    # tablewriter isNumber? tests: 001, 1e3, -2, 1.5 numeric; Inf/NaN? true/false not
    # Try parse as float with Go-like syntax? Use regex
    if re.fullmatch(r'[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?', t):
        return True
    return False

def render_table(columns, rows, opts, markdown=False):
    # rows: list of list of strings (already converted)
    # Wrap and split
    def process_cell(text):
        # split by \n first
        segments=[]
        for part in text.split('\n'):
            if opts.onowrap:
                segments.append(part)
            else:
                segments.extend(wrap_line(part,30))
        return segments
    header_cells=[process_cell(c) for c in columns]
    body_cells=[[process_cell(v) for v in row] for row in rows]
    ncols=len(columns)
    widths=[0]*ncols
    for i in range(ncols):
        for seg in header_cells[i]: widths[i]=max(widths[i], display_width(seg))
        for row in body_cells:
            for seg in row[i]: widths[i]=max(widths[i], display_width(seg))
    def pad_center(s,w):
        dw=display_width(s); pad=w-dw
        left=pad//2; right=pad-left
        return ' '*left+s+' '*right
    def pad_left(s,w):
        return s+' '*(w-display_width(s))
    def pad_right(s,w):
        return ' '*(w-display_width(s))+s
    def format_row(cell_segments_list, is_header=False, original_row=None):
        maxlines=max(len(segs) for segs in cell_segments_list) if cell_segments_list else 1
        lines=[]
        for li in range(maxlines):
            parts=[]
            for i,segs in enumerate(cell_segments_list):
                seg=segs[li] if li < len(segs) else ''
                if is_header:
                    content=pad_center(seg, widths[i])
                else:
                    # alignment determined by the original cell's segment? tablewriter aligns per line segment based on that segment's numeric?
                    # For continuation lines (li>0) if segment is from same original cell, test numeric of segment
                    if _is_numeric_cell(seg):
                        content=pad_right(seg, widths[i])
                    else:
                        content=pad_left(seg, widths[i])
                parts.append(' '+content+' ')
            if markdown:
                lines.append('|'+'|'.join(parts)+'|')
            else:
                lines.append('|'+'|'.join(parts)+'|')
        return lines
    out=[]
    if not markdown:
        border='+'+'+'.join('-'*(w+2) for w in widths)+'+'
        out.append(border)
        out.extend(format_row(header_cells, is_header=True))
        out.append(border)
        for row in body_cells:
            out.extend(format_row(row))
        out.append(border)
    else:
        out.extend(format_row(header_cells, is_header=True))
        out.append('|'+'|'.join('-'*(w+2) for w in widths)+'|')
        for row in body_cells:
            out.extend(format_row(row))
    return '\n'.join(out)+'\n'

class TableWriter(Writer):
    def __init__(self, sink, opts, markdown=False):
        super().__init__(sink,opts); self.markdown=markdown
    def write_result(self, columns, rows):
        str_rows=[_row_strings(columns,row,self.opts) for row in rows]
        self.sink.write(render_table(columns, str_rows, self.opts, self.markdown))

def make_writer(fmt, sink, opts):
    if fmt=='CSV': return CSVWriter(sink,opts,raw=False)
    if fmt=='RAW': return CSVWriter(sink,opts,raw=True)
    if fmt=='JSON': return JSONWriter(sink,opts,lines=False)
    if fmt=='JSONL': return JSONWriter(sink,opts,lines=True)
    if fmt=='LTSV': return LTSVWriter(sink,opts)
    if fmt=='TBLN': return TBLNWriter(sink,opts)
    if fmt=='VF': return VFWriter(sink,opts)
    if fmt=='YAML': return YAMLWriter(sink,opts)
    if fmt=='AT': return TableWriter(sink,opts,markdown=False)
    if fmt=='MD': return TableWriter(sink,opts,markdown=True)
    return CSVWriter(sink,opts,raw=False)

