def quote_display_col(name):
    if name=='':
        return '\\`\\`'
    if any(not (ch.isalnum() or ch=='_') for ch in name) or name.lower() in KEYWORDS_FOR_QUOTE:
        return '\\`'+name+'\\`'
    return name

def quote_arg(token):
    if re.fullmatch(r'[A-Za-z0-9]+', token or ''):
        return token
    return '"' + token.replace("'", "\\'") + '"'

def do_analyze(opts, filearg, only):
    base_token, token_jq = split_jq_token(filearg)
    if token_jq is not None:
        effective=filearg; jq_expr=token_jq
    elif opts.ijq!='':
        effective=filearg+'::'+opts.ijq; jq_expr=opts.ijq
    else:
        effective=filearg; jq_expr=None
    filename_fs=strip_token_quotes(base_token)
    # options clone without inum/inull for analyze reader
    import copy
    opts2=copy.copy(opts)
    opts2.inum=False
    opts2.inull_set=False
    opened=open_table_file(filename_fs, opts2)
    if opened is None:
        # Go open error path: expanded path
        p=expand_home(filename_fs)
        raise Fatal(f'ERROR: open {p}: no such file or directory')
    exp=explicit_format(opts2)
    if exp is not None:
        kind,fmt_name=exp
    else:
        kind,fmt_name,msgs=guess_format(filename_fs, opts2, display_name=base_token)
        for m in msgs: debug_log(m)
    # analyze uses first file only
    disp,data=opened.files[0]
    try:
        reader=create_reader_for_bytes(data, kind, fmt_name, opts2, jq_expr)
    except ImportErr as e:
        raise Fatal(f'ERROR: {e}')
    names=reader.names; types=reader.types
    display_names=[quote_display_col(n) for n in names]
    sample_rows=reader.sample_rows
    fmt_display=reader.fmt_name if hasattr(reader,'fmt_name') else fmt_name
    # reader.fmt_name from result is set based on kind in constructors: CSV reader uses fmt_kind, etc. For explicit itext, reader_text sets Unknown.
    # Correct fmt display: if explicit, use fmt_name from explicit/guess except CSV readers return kind.
    if kind in ('CSV','TSV','PSV'):
        fmt_display=kind
    elif kind=='TEXT':
        fmt_display='Unknown'
    else:
        fmt_display=kind if kind!='TEXT' else 'Unknown'
        if kind=='JSON': fmt_display='JSON'
        if kind=='YAML': fmt_display='YAML'
    is_unknown = (kind=='TEXT')
    if is_unknown:
        sample_rows=[]
    out=[]
    # examples generation
    examples=[]
    if (not is_unknown) and len(sample_rows)>0 and len(names)>0:
        prog=sys.argv[0]
        raw_args=sys.argv[1:]
        cleaned=[]
        i=0
        while i<len(raw_args):
            tok=raw_args[i]
            if tok in ('-a','-A','-ijq'):
                i+=2; continue
            cleaned.append(tok); i+=1
        prefix_parts=[prog]
        for tok in cleaned:
            if tok.startswith('-'):
                prefix_parts.append(tok)
            else:
                prefix_parts.append(quote_arg(tok))
        prefix=' '.join(prefix_parts)
        cols=', '.join(display_names)
        first=display_names[0]
        first_val=value_to_string(sample_rows[0][0]) if sample_rows and sample_rows[0] else ''
        sqls=[
            f'SELECT {cols} FROM {effective}',
            f"SELECT {cols} FROM {effective} WHERE {first} = '{first_val}'",
            f'SELECT {first}, count({first}) FROM {effective} GROUP BY {first}',
            f'SELECT {cols} FROM {effective} ORDER BY {first} LIMIT 10',
        ]
        examples=[f'{prefix} "{sql}"' for sql in sqls]
    if only:
        if examples:
            sys.stdout.write('\n'.join(examples)+'\n')
        return
    out.append(f'The table name is {effective}.')
    out.append(f'The file type is {fmt_display}.')
    # hints
    if len(names)==1:
        if fmt_display=='CSV':
            sample_first=''
            if sample_rows and sample_rows[0]:
                sample_first=value_to_string(sample_rows[0][0])
            suggested=' '
            suggested_disp=' '
            if sample_first.count(';')>=2:
                suggested=';'; suggested_disp=';'
            elif sample_first.count('\t')>=2:
                suggested='\t'; suggested_disp='\\t'
            out.append('Is the delimiter different?')
            out.append(f'Please try again with -id "{suggested_disp}" or other character.')
            if ':' in sample_first:
                out.append('Is it a LTSV file?')
                out.append('Please try again with -iltsv.')
        elif fmt_display=='JSON':
            out.append('Is it for internal objects?')
            first_name=names[0] if names else 'c1'
            out.append(f'Please try again with -ijq ".{first_name}".')
    out.append('')
    out.append('Data types:')
    # types table
    types_rows=[[display_names[i], types[i]] for i in range(len(names))]
    types_table=render_table(['column name','type'], types_rows, opts, markdown=False)
    out.append(types_table.rstrip('\n'))
    out.append('')
    out.append('Data samples:')
    sample_str_rows=[]
    for r in sample_rows:
        sample_str_rows.append([value_to_string(v) for v in r])
    sample_table=render_table(display_names, sample_str_rows, opts, markdown=False)
    out.append(sample_table.rstrip('\n'))
    out.append('')
    out.append('Examples:')
    out.extend(examples)
    sys.stdout.write('\n'.join(out)+'\n')

# ---------------- main ----------------

def print_usage_exit(code=2):
    sys.stderr.write(USAGE)
    return code

def main(argv=None):
    global DEBUG
    if argv is None: argv=sys.argv
    sink=None; conn=None; raw_out=None
    try:
        opts=parse_flags(argv)
        DEBUG=opts.debug
        if opts.version:
            sys.stdout.write(VERSION+'\n')
            return 0
        if opts.help:
            sys.stderr.write(USAGE)
            return 2
        config=load_config(opts)
        if opts.dblist:
            for name, entry in config.database.items():
                sys.stdout.write(f'{name}:{entry.driver}\n')
            return 0
        driver, dsn = select_db(opts, config)
        if opts.A!='':
            do_analyze(opts, opts.A, only=True)
            return 0
        if opts.a!='':
            do_analyze(opts, opts.a, only=False)
            return 0
        # query determination
        query=None
        if opts.t!='':
            query=f'SELECT * FROM {opts.t}'
        elif opts.q!='':
            try:
                with open(opts.q,'rb') as fh: qdata=fh.read()
            except Exception as e:
                raise Fatal(f'ERROR: {go_open_err(opts.q,e)}')
            query=qdata.decode('utf-8','surrogateescape')
        elif opts.args:
            query=' '.join(opts.args)
        else:
            sys.stderr.write(USAGE); return 2
        if query is None or query.strip(' \t\r\n;')=='':
            sys.stderr.write(USAGE); return 2
        # output determination
        explicit_fmt=explicit_output_format(opts)
        guessed_fmt=None; guessed_comp=None
        if opts.out!='' and not opts.out_without_guess:
            guessed_fmt, guessed_comp = guess_output_format_and_compression(opts)
        if explicit_fmt is not None:
            fmt=explicit_fmt
        elif guessed_fmt is not None:
            fmt=guessed_fmt
        else:
            fmt='CSV'
        compression=None
        if opts.oz!='':
            ozlow=opts.oz.lower()
            if ozlow in ('gz','bz2','xz','zstd','lz4'):
                compression=ozlow
            else:
                compression=None
        elif opts.out!='' and not opts.out_without_guess:
            compression=guessed_comp
        # open output
        if opts.out!='':
            if os.path.isdir(opts.out):
                raise Fatal(go_open_err(opts.out, IsADirectoryError()))
            try:
                raw_out=open(opts.out,'wb')
            except Exception as e:
                raise Fatal(go_open_err(opts.out,e))
            sink=Sink(raw_out, compression, is_stdout=False)
            sink.crlf_effective=True
        else:
            sink=Sink(sys.stdout.buffer, compression, is_stdout=True)
            sink.crlf_effective=False
        writer=make_writer(fmt, sink, opts)
        debug_log(f'driver: {driver}, dsn: {dsn}')
        conn=connect_db(driver, dsn)
        tokens=tokenize(query)
        debug_log(''.join(f'[{t}]' for t in tokens))
        cand_indices=extract_candidates(tokens)
        if not cand_indices:
            debug_log('table not found')
        # unique candidates by raw token
        uniq={}
        for idx in cand_indices:
            raw=tokens[idx]
            uniq.setdefault(raw, []).append(idx)
        jq_counter={'n':0}
        imported={}  # raw -> table_name
        for raw, indices in uniq.items():
            table_name=import_candidate(conn, raw, opts, jq_counter)
            if table_name is not None:
                imported[raw]=table_name
                repl=qident(table_name)
                for idx in indices:
                    tokens[idx]=repl
        # split statements
        groups=[]; cur=[]
        for tok in tokens:
            if tok==';':
                groups.append(cur); cur=[]
            else:
                cur.append(tok)
        groups.append(cur)
        statements=[]
        for g in groups:
            stmt=''.join(g).strip()
            statements.append(stmt)
        if statements and statements[-1]=='':
            statements=statements[:-1]
        for stmt in statements:
            debug_log(stmt)
            if stmt=='':
                raise Fatal('export: no SQL statement')
            # first token
            stmt_tokens=tokenize(stmt)
            first=None
            for t in stmt_tokens:
                if is_space_token(t): continue
                first=t; break
            is_select = (first is not None and first.upper()=='SELECT')
            cur=conn.cursor()
            if is_select:
                try:
                    cur.execute(stmt)
                except sqlite3.Error as e:
                    raise Fatal(f'export: {e} [{stmt}]')
                cols=[d[0] for d in cur.description] if cur.description else []
                try:
                    rows=cur.fetchall()
                except sqlite3.Error as e:
                    raise Fatal(f'export: {e} [{stmt}]')
                try:
                    writer.write_result(cols, rows)
                except ExportErr as e:
                    raise Fatal(f'export: {e}')
            else:
                try:
                    cur.execute(stmt)
                except sqlite3.Error as e:
                    raise Fatal(f'export: {e} [{stmt}]')
            cur.close()
        try:
            conn.commit()
        except Exception:
            pass
        sink.flush_final()
        if raw_out: 
            try: raw_out.close()
            except: pass
        return 0
    except SystemExit:
        raise
    except Fatal as e:
        # rollback
        if conn is not None:
            try: conn.rollback()
            except: pass
        if sink is not None:
            try: sink.flush_final()
            except: pass
            if raw_out:
                try: raw_out.close()
                except: pass
        if e.usage:
            sys.stderr.write(USAGE)
            return e.code
        if e.msg:
            log_msg(e.msg)
        return e.code
    except BrokenPipeError:
        return 0

if __name__=='__main__':
    sys.exit(main())
